:root {
  --bg-card: #1a1f2e;
  --bg-header: #111827;
  --bg-metric: #242b3d;
  --bg-metric-primary: #1e3a5f;
  --bg-panel: #1e2537;
  --bg-alert-warn: #3a2a0a;
  --bg-alert-info: #0a2235;
  --accent-blue: #3b9eff;
  --accent-cyan: #22d3ee;
  --accent-yellow: #fbbf24;
  --accent-red: #f87171;
  --accent-green: #34d399;
  --text-primary: #f0f4ff;
  --text-secondary: #8b9ab8;
  --text-muted: #4a5572;
  --border-subtle: #2a3350;
  --needle-color: #f87171;
  --compass-bg: #131825;
}

.weather-dashboard {
  background: var(--bg-card);
  border: 1px solid var(--border-subtle);
  border-radius: 14px;
  width: 480px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
}

.dash-header {
  background: var(--bg-header);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 14px;
  border-bottom: 1px solid var(--border-subtle);
  gap: 10px;
}

.station-info {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.station-label {
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.12em;
  color: var(--text-muted);
  text-transform: uppercase;
}

.station-id {
  font-size: 13px;
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: 0.05em;
}

.dash-title {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
}

.title-main {
  font-size: 13px;
  font-weight: 700;
  color: var(--text-primary);
}

.title-sub {
  font-size: 9px;
  color: var(--text-secondary);
  letter-spacing: 0.03em;
}

.status-badge {
  display: flex;
  align-items: center;
  gap: 4px;
  background: #0d2d0d;
  border: 1px solid #1a5c1a;
  border-radius: 20px;
  padding: 3px 8px;
}

.status-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--accent-green);
}

.status-text {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-green);
  letter-spacing: 0.1em;
}

.metrics-row {
  display: flex;
  gap: 6px;
  padding: 10px 12px 6px;
}

.metric-card {
  background: var(--bg-metric);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 7px 4px 6px;
  margin: 0;
  gap: 1px;
}

.metric-card.primary {
  background: var(--bg-metric-primary);
  border-color: var(--accent-blue);
}

.metric-icon {
  font-size: 15px;
  line-height: 1;
}

.metric-label {
  font-size: 8px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.07em;
  text-align: center;
  margin-top: 1px;
}

.metric-value {
  font-size: 19px;
  font-weight: 800;
  color: var(--text-primary);
  line-height: 1.1;
}

.metric-unit {
  font-size: 9px;
  font-weight: 600;
  color: var(--text-secondary);
}

.metric-trend {
  font-size: 8px;
  font-weight: 700;
  border-radius: 5px;
  padding: 1px 4px;
  margin-top: 2px;
}

.trend-up {
  color: var(--accent-red);
  background: rgba(248, 113, 113, 0.12);
}

.trend-down {
  color: var(--accent-cyan);
  background: rgba(34, 211, 238, 0.12);
}

.trend-stable {
  color: var(--accent-yellow);
  background: rgba(251, 191, 36, 0.12);
}

.bottom-row {
  display: flex;
  gap: 6px;
  padding: 0 12px 12px;
}

.forecast-panel,
.alerts-panel,
.wind-panel {
  background: var(--bg-panel);
  border: 1px solid var(--border-subtle);
  border-radius: 10px;
  padding: 7px 8px 6px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.forecast-panel {
  flex: 2;
}

.alerts-panel {
  flex: 3;
}

.wind-panel {
  flex: 1.6;
  align-items: center;
}

.panel-title {
  font-size: 9px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--accent-blue);
  margin-bottom: 1px;
}

.forecast-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.forecast-item {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 2px 3px;
  border-radius: 5px;
  background: rgba(59, 158, 255, 0.04);
}

.fc-time {
  font-size: 9px;
  color: var(--text-muted);
  font-weight: 600;
  width: 30px;
}

.fc-icon {
  font-size: 11px;
}

.fc-temp {
  font-size: 10px;
  font-weight: 700;
  color: var(--text-primary);
  margin-left: auto;
}

.alert-item {
  display: flex;
  align-items: flex-start;
  gap: 5px;
  padding: 5px 6px;
  border-radius: 7px;
  border-left: 3px solid transparent;
}

.alert-warn {
  background: var(--bg-alert-warn);
  border-left-color: var(--accent-yellow);
}

.alert-info {
  background: var(--bg-alert-info);
  border-left-color: var(--accent-blue);
}

.alert-icon {
  font-size: 11px;
  line-height: 1.4;
}

.alert-text {
  font-size: 9px;
  font-weight: 500;
  color: var(--text-secondary);
  line-height: 1.4;
}

.compass {
  position: relative;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: var(--compass-bg);
  border: 2px solid var(--border-subtle);
  display: flex;
  align-items: center;
  justify-content: center;
}

.compass-n,
.compass-e,
.compass-s,
.compass-w {
  position: absolute;
  font-size: 8px;
  font-weight: 800;
  color: var(--text-muted);
}

.compass-n {
  top: 2px;
  left: 50%;
  transform: translateX(-50%);
  color: var(--accent-red);
}

.compass-s {
  bottom: 2px;
  left: 50%;
  transform: translateX(-50%);
}

.compass-e {
  right: 3px;
  top: 50%;
  transform: translateY(-50%);
}

.compass-w {
  left: 3px;
  top: 50%;
  transform: translateY(-50%);
}

.compass-needle {
  position: absolute;
  width: 3px;
  height: 18px;
  background: var(--needle-color);
  border-radius: 2px;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -100%) rotate(228deg);
  transform-origin: bottom center;
}

.compass-center {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--text-primary);
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  z-index: 1;
}

.wind-dir-label {
  font-size: 9px;
  font-weight: 700;
  color: var(--accent-cyan);
  letter-spacing: 0.05em;
  text-align: center;
}
